public class InnerDaemonTaskDefinitionDaemonContainerDefinitionFactory(Action<Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition> factoryAction = null) : SubResourceFactory<Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition>
{

    internal InnerDaemonTaskDefinitionHealthCheckFactory HealthCheckFactory { get; set; }

    internal InnerDaemonTaskDefinitionLogConfigurationFactory LogConfigurationFactory { get; set; }

    internal InnerDaemonTaskDefinitionFirelensConfigurationFactory FirelensConfigurationFactory { get; set; }

    internal InnerDaemonTaskDefinitionRepositoryCredentialsFactory RepositoryCredentialsFactory { get; set; }

    internal InnerDaemonTaskDefinitionLinuxParametersFactory LinuxParametersFactory { get; set; }

    internal InnerDaemonTaskDefinitionRestartPolicyFactory RestartPolicyFactory { get; set; }

    protected override Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition Create()
    {
        var daemonContainerDefinitionResult = CreateDaemonContainerDefinition();
        factoryAction?.Invoke(daemonContainerDefinitionResult);

        return daemonContainerDefinitionResult;
    }

    private Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition CreateDaemonContainerDefinition()
    {
        var daemonContainerDefinitionResult = new Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition();

        return daemonContainerDefinitionResult;
    }
    public override void CreateChildren(Humidifier.ECS.DaemonTaskDefinitionTypes.DaemonContainerDefinition result)
    {
        base.CreateChildren(result);

        result.HealthCheck ??= HealthCheckFactory?.Build();
        result.LogConfiguration ??= LogConfigurationFactory?.Build();
        result.FirelensConfiguration ??= FirelensConfigurationFactory?.Build();
        result.RepositoryCredentials ??= RepositoryCredentialsFactory?.Build();
        result.LinuxParameters ??= LinuxParametersFactory?.Build();
        result.RestartPolicy ??= RestartPolicyFactory?.Build();
    }

} // End Of Class

